#include <optional>
#include <vector>

/**
 *
 */
namespace bms_parser {
enum class LongNoteType;
inline constexpr int BgaSequenceBlank = -1;

struct BgaPoorSequence {
  std::vector<int> Frames;
};

class TimeLine {
public:
  std::vector<Note *> BackgroundNotes;
  std::vector<Note *> InvisibleNotes;
  std::vector<Note *> Notes;
  std::vector<LandmineNote *> LandmineNotes;
  double Bpm = 0;
  bool BpmChange = false;
  bool BpmChangeApplied = false;
  bool ScrollChange = false;
  bool HasSpeedObject = false;
  int BgaBase = -1;
  int BgaLayer = -1;
  std::optional<BgaPoorSequence> BgaPoor;

  double StopLength = 0;
  std::optional<long long> ParsedStopDuration;
  double Scroll = 1;
  double Speed = 1;

  // musical timing in microseconds
  long long Timing = 0;

  // beat position; measure number + position in
  // measure. 1.25 means 1 measure and 1/4 beat
  double BeatPosition = 0;

  explicit TimeLine(int lanes, bool metaOnly);

  TimeLine *SetNote(int lane, Note *note);

  // O(1) finalization after resolving a player-selected LN mode. May replace
  // and delete this slot's LN; call before caching note pointers or playback.
  // Counts are the caller's responsibility. Detached ownership stays in Chart.
  Note *DemoteUnusableLongNote(int lane, LongNoteType resolvedType);

  TimeLine *SetInvisibleNote(int lane, Note *note);

  TimeLine *SetLandmineNote(int lane, LandmineNote *note);

  TimeLine *AddBackgroundNote(Note *note);

  [[nodiscard]] double GetStopDuration() const;

  ~TimeLine();
  bool IsFirstInMeasure = false;
};
} // namespace bms_parser

