namespace bms_parser {
// BMSModelUtils counts timelines in [0, Integer.MAX_VALUE) after Java's
// narrowing conversion of microseconds / 1000 to an int.
inline bool IsCountedNoteTime(long long microseconds) {
  return static_cast<std::uint32_t>(microseconds / 1000) < 0x7fffffffU;
}

enum class JudgeRankType { BmsRank, DefExRank };

class ChartMeta {
public:
  std::string SHA256;
  std::string MD5;
  std::filesystem::path BmsPath;
  std::filesystem::path Folder;
  std::string Artist;
  std::string SubArtist;
  double Bpm = 0;
  std::string Genre;
  std::string Title;
  std::string SubTitle;
  int Rank = 2;
  JudgeRankType RankType = JudgeRankType::BmsRank;
  double Total = 100;
  bool HasTotal = false;
  int VolWav = 0;
  // Java BMSModel custom %/@ values: case-sensitive keys, untrimmed values.
  std::unordered_map<std::string, std::string> Values;
  long long PlayLength = 0; // Timing of the last playable note, in microseconds
  // End of the final measure, including its trailing silence, in microseconds.
  long long TotalLength = 0;
  std::filesystem::path Banner;
  std::filesystem::path StageFile;
  std::filesystem::path BackBmp;
  std::filesystem::path Preview;
  bool BgaPoorDefault = false;
  int Difficulty = 0;
  double PlayLevel = 3;
  // BMSDecoder keeps the normalized header string and SongData later applies
  // Java Integer.parseInt. The numeric field alone loses invalid/decimal input.
  std::string PlayLevelText;
  double MinBpm = 0;
  double MaxBpm = 0;
  double MostPrevalentBpm = 0;
  double GuessedBeatBpm = 0;
  int GuessedBeatsPerMeasure = 4;
  int Player = 1;
  int KeyMode = 5;
  bool IsDP = false;
  // Scoring judgements: LN heads, both CN/HCN endpoints, excluding mines.
  int TotalNotes = 0;
  int TotalLongNotes = 0;
  int TotalScratchNotes = 0;
  int TotalBackSpinNotes = 0;
  int TotalLandmineNotes = 0;
  int LnMode = 0; // 0: user decides, 1: LN, 2: CN, 3: HCN
  std::optional<unsigned int> RandomSeed;
  std::optional<std::string> RandomPrng;
  std::vector<int> RandomValues;

  [[nodiscard]] int GetKeyLaneCount() const { return KeyMode; }
  [[nodiscard]] bool IsScratchlessKeyMode() const {
    return KeyMode == 4 || KeyMode == 6 || KeyMode == 8;
  }
  [[nodiscard]] int GetScratchLaneCount() const {
    // Only legacy beat modes synthesize scratch lanes. Other positive key
    // counts describe dense key lanes unless a format-specific map above says
    // otherwise.
    if (KeyMode == 10 || KeyMode == 14) {
      return 2;
    }
    if (KeyMode == 5 || KeyMode == 7) {
      return IsDP ? 2 : 1;
    }
    return 0;
  }
  [[nodiscard]] int GetTotalLaneCount() const {
    return KeyMode + GetScratchLaneCount();
  }

  [[nodiscard]] std::vector<int> GetKeyLaneIndices() const {
    switch (KeyMode) {
    case 4:
      return {0, 1, 3, 4};
    case 5:
      return {0, 1, 2, 3, 4};
    case 6:
      return {0, 1, 2, 4, 5, 6};
    case 7:
      return {0, 1, 2, 3, 4, 5, 6};
    case 8:
      return {7, 0, 1, 2, 3, 4, 5, 6};
    case 10:
      return {0, 1, 2, 3, 4, 8, 9, 10, 11, 12};
    case 14:
      return {0, 1, 2, 3, 4, 5, 6, 8, 9, 10, 11, 12, 13, 14};
    default:
      if (KeyMode <= 0) {
        return {};
      }
      std::vector<int> lanes;
      lanes.reserve(static_cast<std::size_t>(KeyMode));
      for (int lane = 0; lane < KeyMode; ++lane) {
        lanes.push_back(lane);
      }
      return lanes;
    }
  }

  [[nodiscard]] std::vector<int> GetScratchLaneIndices() const {
    const int scratchLaneCount = GetScratchLaneCount();
    if (scratchLaneCount == 0) {
      return {};
    }
    if (scratchLaneCount == 2) {
      return {7, 15};
    }
    return {7};
  }

  [[nodiscard]] std::vector<int> GetTotalLaneIndices() const {
    std::vector<int> Result;
    std::vector<int> keyLaneIndices = GetKeyLaneIndices();
    std::vector<int> scratchLaneIndices = GetScratchLaneIndices();
    if (!scratchLaneIndices.empty()) {
      Result.push_back(scratchLaneIndices.front());
    }
    Result.insert(Result.end(), keyLaneIndices.begin(), keyLaneIndices.end());
    if (scratchLaneIndices.size() > 1) {
      Result.push_back(scratchLaneIndices[1]);
    }

    return Result;
  }
};

class Chart {
public:
  Chart();
  ~Chart();
  Chart(const Chart &) = delete;
  Chart &operator=(const Chart &) = delete;
  Chart(Chart &&other) noexcept;
  Chart &operator=(Chart &&other) noexcept;
  ChartMeta Meta;
  std::vector<Measure *> Measures;
  // Own LN partners displaced from timeline slots by later source rows.
  std::vector<std::unique_ptr<Note>> DetachedNotes;
  std::unordered_map<int, std::string> WavTable;
  std::unordered_map<int, std::string> ReferencedWavTable;
  std::unordered_map<int, std::string> BmpTable;
  std::unordered_map<int, std::string> ReferencedBmpTable;

private:
  void Swap(Chart &other) noexcept;
};
} // namespace bms_parser


